  /// the composed dim detail. Unknown ids are ignored.
  void settle(
    String id, {
    required TaskBlockState state,
    double? elapsed,
    int? exitCode,
    String? detail,
  }) {
    for (var i = _cards.length - 1; i >= 0; i--) {
