            t,
            () => shellJobLiveSummaryLine(
              total: _countOfTurn(t, (_) => true),
              running: _countOfTurn(
                t,
                (c) => c.state == TaskBlockState.running,
              ),
              done: _countOfTurn(t, (c) => c.state == TaskBlockState.done),
