      required List<int> repaint,
      required List<List<_Cell>> next}) {
    _output.write(k > 0 ? '\x1b[${k}S' : '\x1b[${-k}T');
    final from = k > 0 ? next.length - k : 0;
    final to = k > 0 ? next.length : -k;
    for (var row = from; row < to; row++) {
