  /// [terminal]. Called automatically by [spawn]; idempotent.
  void startListening() {
    if (_listening) return;
    _listening = true;
    _outputSub = pty.out.listen((text) {
      _rawBuffer.write(text);
      terminal.write(text);
    });
  }

