      }

      for (var col = 0; col < cols; col++) {
        final nextCell =
            col < nextRow.length ? nextRow[col] : const _Cell(' ', '');
        // Beyond the previously WRITTEN row length the physical terminal
        // holds ERASED cells (CSI K / CSI 2J leave zero-width empty cells in
