        statusIdx = i;
        break;
      }
    }
    if (statusIdx >= 0) {
      // Live frame: below the status row only chrome (blank, rule, composer).
      for (var i = statusIdx + 1; i < viewport.length; i++) {
        expect(
          boardRow.hasMatch(viewport[i]),
