  /// Closes ESU after the frame's last byte; the cursor apply stays outside
  /// the atomic region (matches [AnsiRenderer]'s ordering).
  void _syncEnd() {
    if (_syncOpen) {
      _output.write('\x1b[?2026l');
      _syncOpen = false;
