    var lastCol = -1;
    var lastAttrs = '';
    var lastHyperlink = '';
    var wrote = false;

    for (var row = 0; row < rows; row++) {
      final nextRow = row < next.length ? next[row] : const <_Cell>[];
      final prevRow =
          (prev != null && row < prev.length) ? prev[row] : const <_Cell>[];
      final cols =
          nextRow.length > prevRow.length ? nextRow.length : prevRow.length;

