            '${viewport.join('\n')}',
      );
    } else {
      // Idle collapse: the composer prompt row is the frame's last row.
      expect(
        viewport.last.trimRight(),
        startsWith('╰─'),
        reason: 'idle chrome collapses to the composer prompt row:\n'
