          if (lastHyperlink.isNotEmpty) _output.write('\x1b]8;;\x1b\\');
          if (nextCell.hyperlink.isNotEmpty) {
            _output.write(nextCell.hyperlink);
          }
          lastHyperlink = nextCell.hyperlink;
