          // _paintRow homes the cursor per row and closes SGR/hyperlinks;
          // forget the tracked position so the next surgical write always
          // re-addresses absolutely.
          lastRow = -1;
          lastCol = -1;
          lastAttrs = '';
          lastHyperlink = '';
